{
  "summary": "Implements local tracking of recent stale chain tips to support BIP 332 stale tip relay. It adds an AcceptedStaleTip validation notification, a bounded StaleTipTracker seeded from the block index, and a -staletips option to enable tracking without P2P message relay. It also extends the getchaintips RPC with fork_point, max_depth, and staletips_only parameters.",
  "problem": "Nodes currently do not retain or easily surface recent stale tips in an efficient, bounded structure suitable for BIP 332 stale tip relay. Additionally, getchaintips requires callers to scan every historical fork to locate recent stale branches and determine where they diverged from the active chain.",
  "evidence": [
    "Part of tracking issue #36833 for implementing BIP 332 Stale Tip Relay",
    "Commit ba50132662 notes that max_depth and fork_point 'lets callers find recent forks without listing every old stale branch on mainnet or walking back each branch to its fork point'"
  ],
  "dependencies": {
    "depends_on": [],
    "enables": [
      "#36920"
    ]
  },
  "scope_notes": "Adds validation interface notifications, net_processing tracker state, and RPC changes; no P2P protocol changes are introduced yet as network relay is deferred to follow-up work.",
  "changed_since_previous": "",
  "card": "Adds local tracking of recent stale tips behind a new -staletips configuration option, serving as the foundation for BIP 332 stale tip relay. The PR introduces an AcceptedStaleTip validation notification, a bounded memory tracker initialized from the block index, and updates getchaintips with fork_point, max_depth, and staletips_only options. It implements part of the BIP 332 tracking issue (#36833) without enabling network P2P relay yet, and unblocks PR #36920.",
  "needs": [
    "diff"
  ],
  "confidence": "medium",
  "uncertainties": [
    "The full diff and file list were unavailable, limiting direct inspection of memory bounds and validation notification locking."
  ],
  "risk": {
    "level": "medium",
    "touches": [
      "validation",
      "p2p",
      "rpc_api"
    ],
    "why": "Flaws in validation notifications or index traversals during startup could introduce startup performance degradation or crashes, though stale tip tracking is disabled by default."
  }
}
